body,
html {
    height: 100%;
    width: 100%;
    overflow: hidden;
}

#wrap {
    position: relative;
    height: 100%;
    width: 100%;
}

#alert-box {
    height: 100%;
    width: 100%;
    position: absolute;
}

#alert-box.hidden,
.hidden {
    opacity: 0;
}

#alert-text {
    padding: 20px;
    text-shadow: 0px 0px 1px #000, 0px 0px 2px #000, 0px 0px 3px #000, 0px 0px 4px #000, 0px 0px 5px #000;
}

#alert-message,
#alert-user-message {
    text-align: center;
}

#alert-user-message img {
    vertical-align: middle;
    height: 1em;
}

#alert-image {
    position: relative;
}

#alert-image video {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

#alert-message > span > span {
    display: inline-block;
}

